            <button onClick={onClose} className="px-6 py-2.5 rounded-lg border border-gray-200 bg-white text-gray-700 font-medium text-sm hover:bg-gray-50 hover:border-gray-300 transition-colors shadow-sm">
              Close
            </button>
            <button 
              onClick={handleUpdateSelected} 
              disabled={selectedSiteIds.size === 0}
              className="px-6 py-2.5 rounded-lg bg-gray-900 hover:bg-gray-800 text-white font-medium text-sm transition-all shadow-md hover:shadow-lg flex items-center gap-2 disabled:opacity-50 disabled:shadow-none disabled:cursor-not-allowed"
            >
              <RefreshCw className="w-4 h-4" /> Update Selected
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { X, Building2, RefreshCw, CheckCircle2, ArrowRight, Square, CheckSquare, ChevronDown, Search, Filter } from 'lucide-react';
import { Site, Template } from '../types';

const getStatusStyles = (status: string) => {
  switch (status) {
    case 'Active': return 'text-emerald-700 bg-emerald-50 border-emerald-200';
    case 'Needs Update': return 'text-amber-700 bg-amber-50 border-amber-200';
    default: return 'text-gray-700 bg-gray-50 border-gray-200';
  }
};

interface SiteDetailsModalProps {
  isOpen: boolean;
  onClose: () => void;
  template: Template | null;
  allTemplates: Template[];
  sites: Site[];
  onUpdateSites: (templateId: string, siteIds: string[]) => void;
  onSelectTemplate: (template: Template) => void;
}

export const SiteDetailsModal: React.FC<SiteDetailsModalProps> = ({ isOpen, onClose, template, allTemplates, sites, onUpdateSites, onSelectTemplate }) => {
  const [selectedSiteIds, setSelectedSiteIds] = useState<Set<string>>(new Set());
  const [searchQuery, setSearchQuery] = useState('');
  const [statusFilter, setStatusFilter] = useState<'All' | 'Needs Update' | 'Active'>('All');
  const [versionFilter, setVersionFilter] = useState<string>('All');

  // Use the rolling/published version if we are currently looking at a draft
  const activeVersion = useMemo(() => {
    if (!template) return '';
    // If it's a draft, the "target" for updates is the previous version (the one currently live/rolling out)
    if (template.status === 'Draft' && template.previousVersion) return template.previousVersion;
    return template.version;
  }, [template]);

  // Only allow updates if the target version is a major release (X.0)
  const isTargetMajor = activeVersion.endsWith('.0');

  useEffect(() => {
    // Reset selection when template changes or modal opens
    setSelectedSiteIds(new Set());
    setSearchQuery('');
    setStatusFilter('All');
    setVersionFilter('All');
  }, [isOpen, template?.id]);

  const uniqueVersions = useMemo(() => {
    return Array.from(new Set(sites.map(s => s.version))).sort((a, b) => parseFloat(b as string) - parseFloat(a as string));
  }, [sites]);

  const filteredSites = useMemo(() => {
    return sites.filter(site => {
      // Search
      if (searchQuery && !site.name.toLowerCase().includes(searchQuery.toLowerCase())) {
        return false;
      }

      const needsUpdate = site.version !== activeVersion && isTargetMajor;

      // Status Filter
      if (statusFilter === 'Needs Update' && !needsUpdate) return false;
      if (statusFilter === 'Active' && needsUpdate) return false;

      // Version Filter
      if (versionFilter !== 'All' && site.version !== versionFilter) return false;

      return true;
    });
  }, [sites, searchQuery, statusFilter, versionFilter, activeVersion, isTargetMajor]);

  if (!isOpen || !template) return null;

  // Calculating bulk actions based on filtered view
  const sitesNeedingUpdateInView = filteredSites.filter(s => s.version !== activeVersion && isTargetMajor);
  const canUpdateCount = sitesNeedingUpdateInView.length;

  // Check if all *updateable* sites in current view are selected
  const areAllUpdateableSelected = canUpdateCount > 0 && sitesNeedingUpdateInView.every(s => selectedSiteIds.has(s.id));

  const handleToggleSelect = (siteId: string) => {
    const newSelected = new Set(selectedSiteIds);
    if (newSelected.has(siteId)) {
      newSelected.delete(siteId);
    } else {
      newSelected.add(siteId);
    }
    setSelectedSiteIds(newSelected);
  };

  const handleSelectAll = () => {
    if (areAllUpdateableSelected) {
      // Deselect all visible updateable sites
      const newSelected = new Set(selectedSiteIds);
      sitesNeedingUpdateInView.forEach(s => newSelected.delete(s.id));
      setSelectedSiteIds(newSelected);
    } else {
      // Select all visible updateable sites
      const newSelected = new Set(selectedSiteIds);
      sitesNeedingUpdateInView.forEach(s => newSelected.add(s.id));
      setSelectedSiteIds(newSelected);
    }
  };

  const handleUpdateSelected = () => {
    onUpdateSites(template.id, Array.from(selectedSiteIds));
    setSelectedSiteIds(new Set());
  };

  const handleUpdateSingle = (siteId: string) => {
     onUpdateSites(template.id, [siteId]);
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-gray-900/40 backdrop-blur-sm p-4 animate-in fade-in duration-200">
      <div className="bg-white rounded-2xl shadow-2xl w-full max-w-4xl overflow-hidden flex flex-col max-h-[90vh] ring-1 ring-gray-200">
        {/* Header */}
        <div className="flex items-center justify-between p-6 border-b border-gray-100 bg-white">
          <div className="flex items-center gap-3">
            <div className="p-2 bg-gray-100 text-gray-600 rounded-lg">
              <Building2 className="w-5 h-5" />
            </div>
            <div>
              <h2 className="text-xl font-semibold text-gray-900">Manage Sites</h2>
              <p className="text-sm text-gray-500 mt-1">Review and deploy version updates to participating sites.</p>
            </div>
          </div>
          <button onClick={onClose} className="p-2 text-gray-400 hover:text-gray-600 rounded-full hover:bg-gray-100 transition-colors">
            <X className="w-5 h-5" />
          </button>
        </div>

        {/* Template Info Sub-header */}
        <div className="px-6 py-4 bg-gray-50 border-b border-gray-200 flex flex-col sm:flex-row sm:items-center justify-between gap-4">
           <div className="flex items-center gap-2">
             <span className="text-sm font-medium text-gray-700">Target Release:</span>
             <span className="text-sm font-bold text-gray-900">{template.name}</span>
             <span className="px-2 py-0.5 rounded-full bg-indigo-50 text-indigo-700 border border-indigo-100 text-[10px] font-mono font-bold">v{activeVersion}</span>
           </div>
        </div>

        {/* Filters Toolbar */}
        <div className="px-6 py-3 border-b border-gray-200 bg-white grid grid-cols-12 gap-4 items-center">
            {/* Search */}
            <div className="col-span-12 sm:col-span-5 relative">
                <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
                <input 
                  type="text" 
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                  placeholder="Search sites..." 
                  className="w-full pl-9 pr-3 py-2 text-sm border border-gray-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-indigo-100 focus:border-indigo-300"
                />
            </div>

            {/* Filters */}
            <div className="col-span-6 sm:col-span-3">
               <div className="relative">
                  <select 
                    value={statusFilter}
                    onChange={(e) => setStatusFilter(e.target.value as any)}
                    className="w-full pl-3 pr-8 py-2 text-sm border border-gray-200 rounded-lg appearance-none bg-white focus:outline-none focus:ring-2 focus:ring-indigo-100 focus:border-indigo-300 cursor-pointer text-gray-600"
                  >
                    <option value="All">All Status</option>
                    <option value="Needs Update">Needs Update</option>
                    <option value="Active">Active</option>
                  </select>
                  <Filter className="absolute right-3 top-1/2 -translate-y-1/2 w-3.5 h-3.5 text-gray-400 pointer-events-none" />
               </div>
            </div>

            <div className="col-span-6 sm:col-span-4">
               <div className="relative">
                  <select 
                    value={versionFilter}
                    onChange={(e) => setVersionFilter(e.target.value)}
                    className="w-full pl-3 pr-8 py-2 text-sm border border-gray-200 rounded-lg appearance-none bg-white focus:outline-none focus:ring-2 focus:ring-indigo-100 focus:border-indigo-300 cursor-pointer text-gray-600"
                  >
                    <option value="All">All Versions</option>
                    {uniqueVersions.map(v => (
                      <option key={v as string} value={v as string}>Version {v as string}</option>
                    ))}
                  </select>
                  <ChevronDown className="absolute right-3 top-1/2 -translate-y-1/2 w-3.5 h-3.5 text-gray-400 pointer-events-none" />
               </div>
            </div>
        </div>

        {/* Body */}
        <div className="flex-1 overflow-y-auto bg-white">
          <div className="p-6">
            <div className="bg-white rounded-xl border border-gray-200 shadow-sm overflow-hidden">
              {/* Table Header */}
              <div className="grid grid-cols-12 gap-4 px-6 py-3 bg-gray-50 text-xs font-semibold text-gray-500 uppercase tracking-wider border-b border-gray-200 items-center">
                <div className="col-span-5 flex items-center gap-3">
                   <button 
                      onClick={handleSelectAll} 
                      disabled={canUpdateCount === 0}
                      className="text-gray-400 hover:text-indigo-600 transition-colors disabled:opacity-30 disabled:cursor-not-allowed"
                      title={areAllUpdateableSelected ? "Deselect All Needs Update" : "Select All Needs Update"}
                    >
                        {areAllUpdateableSelected && canUpdateCount > 0 ? (
                          <CheckSquare className="w-4 h-4 text-indigo-600" />
                        ) : (
                          <Square className="w-4 h-4" />
                        )}
                    </button>
                   <span>Site Name</span>
                </div>
                <div className="col-span-3">Current Version</div>
                <div className="col-span-2">Status</div>
                <div className="col-span-2 text-right">Action</div>
              </div>

              {/* Site List */}
              {filteredSites.length > 0 ? (
                <div className="divide-y divide-gray-100">
                  {filteredSites.map(site => {
                    // Logic: Needs Update if versions differ AND target is major version
                    const needsUpdate = site.version !== activeVersion && isTargetMajor;
                    const statusLabel = needsUpdate ? 'Needs Update' : 'Active';
                    const isSelected = selectedSiteIds.has(site.id);

                    return (
                      <div key={site.id} className={`grid grid-cols-12 gap-4 px-6 py-4 items-center text-sm transition-colors ${isSelected ? 'bg-indigo-50/30' : ''}`}>
                        <div className="col-span-5 flex items-center gap-3">
                          {needsUpdate ? (
                             <button onClick={() => handleToggleSelect(site.id)} className="text-gray-300 hover:text-indigo-600">
                               {isSelected ? <CheckSquare className="w-4 h-4 text-indigo-600" /> : <Square className="w-4 h-4" />}
                             </button>
                          ) : (
                             <div className="w-4 h-4 flex items-center justify-center" title="Active">
                               <CheckCircle2 className="w-3.5 h-3.5 text-emerald-300" />
                             </div>
                          )}
                          <div className="flex flex-col">
                             <span className="font-medium text-gray-800 truncate" title={site.name}>{site.name}</span>
                             <span className="text-[10px] text-gray-400 font-mono">ID: {site.id}</span>
                          </div>
                        </div>
                        <div className="col-span-3 font-mono text-gray-600 flex items-center">
                          <span className={`px-2 py-0.5 rounded border ${needsUpdate ? 'bg-amber-50 border-amber-100 text-amber-700' : 'bg-gray-50 border-gray-200'}`}>v{site.version}</span>
                          {needsUpdate && (
                            <>
                              <ArrowRight className="w-3 h-3 mx-2 text-gray-300" />
                              <span className="font-bold text-indigo-700">v{activeVersion}</span>
                            </>
                          )}
                        </div>
                        <div className="col-span-2">
                          <span className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium border whitespace-nowrap ${getStatusStyles(statusLabel)}`}>
                            {statusLabel}
                          </span>
                        </div>
                        <div className="col-span-2 text-right">
                          {needsUpdate ? (
                            <button
                              onClick={() => handleUpdateSingle(site.id)}
                              className="text-xs font-semibold text-indigo-600 bg-indigo-50 hover:bg-indigo-100 px-3 py-1.5 rounded-md transition-colors flex items-center gap-1.5 ml-auto border border-indigo-100"
                            >
                              <RefreshCw className="w-3 h-3" /> Update
                            </button>
                          ) : (
                            <span className="text-xs font-medium text-emerald-600 flex items-center justify-end gap-1.5">
                              <CheckCircle2 className="w-4 h-4" /> Done
                            </span>
                          )}
                        </div>
                      </div>
                    );
                  })}
                </div>
              ) : (
                <div className="text-center py-12 text-sm text-gray-400 flex flex-col items-center">
                  <Search className="w-8 h-8 text-gray-200 mb-2" />
                  <p>No sites match your filters.</p>
                  <button 
                    onClick={() => { setSearchQuery(''); setStatusFilter('All'); setVersionFilter('All'); }}
                    className="mt-2 text-indigo-600 hover:underline"
                  >
                    Clear all filters
                  </button>
                </div>
              )}
            </div>
          </div>
        </div>

        {/* Footer */}
        <div className="p-6 border-t border-gray-100 bg-gray-50/80 flex justify-between items-center gap-3">
          <div className="text-sm text-gray-500">
            {selectedSiteIds.size > 0 ? (
               <span className="font-medium text-indigo-600">{selectedSiteIds.size} site(s) selected for update</span>
            ) : (
               <span>Select sites to bulk update</span>
            )}
          </div>
          <div className="flex gap-3">
            <button onClick={onClose} className="px-6 py-2.5 rounded-lg border border-gray-200 bg-white text-gray-700 font-medium text-sm hover:bg-gray-50 hover:border-gray-300 transition-colors shadow-sm">
              Close
            </button>
            <button 
              onClick={handleUpdateSelected} 
              disabled={selectedSiteIds.size === 0}
              className="px-6 py-2.5 rounded-lg bg-gray-900 hover:bg-gray-800 text-white font-medium text-sm transition-all shadow-md hover:shadow-lg flex items-center gap-2 disabled:opacity-50 disabled:shadow-none disabled:cursor-not-allowed"
            >
              <RefreshCw className="w-4 h-4" /> Update Selected
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useMemo } from 'react';
import { 
  Plus, 
  Search,
  ChevronLeft,
  ChevronRight,
  Building2,
  Clock,
  User,
  Eye,
  PenLine,
  Beaker
} from 'lucide-react';
import { Template, Site, Skeleton } from '../types';

interface TemplateListProps {
  templates: Template[];
  skeletons: Skeleton[];
  sitesByTemplate: Record<string, Site[]>;
  onSelectTemplate: (template: Template) => void;
  onSelectVersion: (template: Template, version: string) => void;
  onCreateTemplate: () => void;
  onCreateSkeleton: () => void;
  onEditSkeleton: (skeleton: Skeleton) => void;
  onArchiveSkeleton: (skeletonId: string) => void;
  onTestLogic: (template: Template) => void;
  onArchive: (templateId: string) => void;
  onUpdateSite: (templateId: string, siteId: string) => void;
  onOpenSiteDetails: (template?: Template) => void;
  onCreateDraft?: (template: Template) => void;
}

const getStatusStyles = (status: string) => {
  switch (status) {
    case 'Published':
      return 'text-emerald-700 bg-emerald-50 border-emerald-200 font-bold';
    case 'Rolling Out':
      return 'text-purple-700 bg-purple-50 border-purple-200 font-bold';
    case 'Draft':
      return 'text-amber-700 bg-amber-50 border-amber-200 font-bold';
    case 'Archived':
      return 'text-gray-700 bg-gray-50 border-gray-200';
    case 'Snapshot':
      return 'text-slate-600 bg-slate-100 border-slate-200';
    default:
      return 'text-gray-700 bg-gray-50 border-gray-200';
  }
};

interface VersionRowProps {
  version: string;
  status: string;
  lastUpdated: string;
  updatedBy: string;
  isCurrent: boolean;
  onView: () => void;
  onEdit?: () => void;
}

const VersionRow: React.FC<VersionRowProps> = ({ 
  version, 
  status, 
  lastUpdated, 
  updatedBy, 
  isCurrent, 
  onView,
  onEdit
}) => {
  const isDraft = status === 'Draft';

  return (
    <tr className={`group transition-colors hover:bg-gray-50/50 ${isCurrent ? 'bg-indigo-50/10' : ''}`}>
      <td className="px-6 py-4 whitespace-nowrap">
        <button 
          onClick={(e) => { e.stopPropagation(); isDraft && onEdit ? onEdit() : onView(); }}
          className="flex items-center gap-2 group/ver outline-none text-left"
        >
           <span className={`font-mono text-sm transition-all ${
             isCurrent 
               ? 'font-bold text-indigo-700' 
               : 'font-semibold text-gray-900 group-hover/ver:text-indigo-600 group-hover/ver:underline'
           }`}>
             v{version}
           </span>
        </button>
      </td>

      <td className="px-6 py-4 whitespace-nowrap">
        <span className={`inline-flex items-center px-2.5 py-1 rounded-full text-[10px] uppercase tracking-wider border ${getStatusStyles(status)}`}>
          {status}
        </span>
      </td>

      <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
          <div className="flex items-center gap-1.5">
             <Clock className="w-3.5 h-3.5 text-gray-400" />
             {lastUpdated}
          </div>
      </td>

      <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
          <div className="flex items-center gap-1.5">
             <User className="w-3.5 h-3.5 text-gray-400" />
             {updatedBy}
          </div>
      </td>

      <td className="px-6 py-4 whitespace-nowrap text-sm text-right">
        <div className="flex items-center justify-end gap-2">
            {isDraft && onEdit && (
              <button
                onClick={(e) => { e.stopPropagation(); onEdit(); }}
                className="inline-flex items-center gap-1.5 px-3 py-1.5 rounded-lg border border-indigo-200 bg-indigo-50 text-indigo-700 text-xs font-medium transition-colors shadow-sm hover:bg-indigo-100"
              >
                <PenLine className="w-3.5 h-3.5" />
                Edit
              </button>
            )}
            <button
              onClick={(e) => { e.stopPropagation(); onView(); }}
              className="inline-flex items-center gap-1.5 px-3 py-1.5 rounded-lg border border-gray-200 bg-white text-gray-700 text-xs font-medium hover:bg-gray-50 hover:text-indigo-600 transition-colors shadow-sm"
            >
              <Eye className="w-3.5 h-3.5" />
              Preview
            </button>
        </div>
      </td>
    </tr>
  );
};

export const TemplateList: React.FC<TemplateListProps> = ({ templates, sitesByTemplate, onSelectVersion, onCreateTemplate, onOpenSiteDetails, onTestLogic, onCreateDraft }) => {
  const [searchQuery, setSearchQuery] = useState('');
  const [currentPage, setCurrentPage] = useState(1);
  const itemsPerPage = 10;

  const activeTemplate = templates.length > 0 ? templates[0] : null;

  const versions = useMemo(() => {
      if (!activeTemplate) return [];

      const list = [
          {
              version: activeTemplate.version,
              status: activeTemplate.status,
              lastUpdated: activeTemplate.lastUpdated,
              updatedBy: activeTemplate.updatedBy || 'Unknown',
              isCurrent: true
          }
      ];

      if (activeTemplate.history && activeTemplate.history.length > 0) {
          activeTemplate.history.forEach(h => {
              const verNum = parseFloat(h.version);

              let inferredStatus: Template['status'];
              if (activeTemplate.status === 'Draft' && h.version === activeTemplate.previousVersion) {
                  inferredStatus = 'Rolling Out';
              } else {
                  const isMajor = h.version.endsWith('.0');
                  inferredStatus = isMajor ? 'Published' : 'Archived';

                  if (!isMajor || (activeTemplate.previousVersion && parseFloat(h.version) < parseFloat(activeTemplate.previousVersion))) {
                      inferredStatus = 'Archived';
                  }
              }

              list.push({
                  version: h.version,
                  status: inferredStatus,
                  lastUpdated: h.lastUpdated,
                  updatedBy: h.updatedBy,
                  isCurrent: false
              });
          });
      }

      if (searchQuery) {
          return list.filter(v => v.version.includes(searchQuery) || v.updatedBy.toLowerCase().includes(searchQuery.toLowerCase()));
      }

      return list.sort((a, b) => parseFloat(b.version) - parseFloat(a.version));
  }, [activeTemplate, searchQuery]);

  const totalPages = Math.ceil(versions.length / itemsPerPage);
  const startIndex = (currentPage - 1) * itemsPerPage;
  const endIndex = startIndex + itemsPerPage;
  const currentVersions = versions.slice(startIndex, endIndex);

  const handlePageChange = (page: number) => {
    if (page >= 1 && page <= totalPages) {
      setCurrentPage(page);
    }
  };

  const handleEditVersion = (versionItem: any) => {
      onSelectVersion(activeTemplate!, versionItem.version);
  };

  const handleViewVersion = (versionItem: any) => {
      const snapshotTemplate: Template = {
          ...activeTemplate!,
          version: versionItem.version,
          status: versionItem.status as Template['status'],
          lastUpdated: versionItem.lastUpdated,
          updatedBy: versionItem.updatedBy,
          blocks: activeTemplate!.history?.find(h => h.version === versionItem.version)?.blocksSnapshot || activeTemplate!.blocks
      };
      onTestLogic(snapshotTemplate);
  };

  if (!activeTemplate) return null;

  return (
    <div>
      <div className="flex flex-col md:flex-row justify-between items-start md:items-end gap-6 mb-8">
        <div>
          <h1 className="text-4xl font-serif font-bold text-gray-900 tracking-tight">{activeTemplate.name}</h1>
        </div>
        <div className="flex items-center gap-3">
          <button 
            onClick={() => onOpenSiteDetails(activeTemplate)}
            className="px-5 py-2.5 rounded-lg border border-gray-200 bg-white text-gray-700 text-sm font-medium hover:bg-gray-50 hover:border-gray-300 transition-all flex items-center gap-2 shadow-sm"
          >
            <Building2 className="w-4 h-4 text-gray-500" /> Manage Sites
          </button>

          <button 
            onClick={() => onCreateDraft?.(activeTemplate)}
            className="px-5 py-2.5 rounded-lg bg-indigo-600 hover:bg-indigo-700 text-white text-sm font-bold transition-all flex items-center gap-2 shadow-md hover:shadow-lg"
          >
            <Plus className="w-4 h-4" /> Create Draft
          </button>
        </div>
      </div>

      <div className="flex flex-col sm:flex-row justify-between items-center gap-4 mb-6">
        <div className="flex flex-col gap-1 w-full sm:w-[320px] sm:ml-auto">
          <div className="relative">
            <input 
              type="text" 
              placeholder="Search versions..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="w-full pl-9 pr-4 py-2 rounded-md border border-gray-200 bg-white text-sm focus:outline-none focus:ring-1 focus:ring-indigo-500 transition-all placeholder:text-gray-400 shadow-sm"
            />
            <Search className="w-4 h-4 text-gray-400 absolute left-3 top-1/2 -translate-y-1/2" />
          </div>
        </div>
      </div>

      <div className="bg-white rounded-xl shadow-sm border border-gray-200 overflow-hidden flex flex-col">
        <div className="overflow-x-auto">
          <table className="min-w-full divide-y divide-gray-100">
            <thead className="bg-gray-50/50">
              <tr>
                <th scope="col" className="px-6 py-3 text-left text-xs font-bold text-gray-500 uppercase tracking-wider">Version</th>
                <th scope="col" className="px-6 py-3 text-left text-xs font-bold text-gray-500 uppercase tracking-wider">Status</th>
                <th scope="col" className="px-6 py-3 text-left text-xs font-bold text-gray-500 uppercase tracking-wider">Last Updated</th>
                <th scope="col" className="px-6 py-3 text-left text-xs font-bold text-gray-500 uppercase tracking-wider">Updated By</th>
                <th scope="col" className="relative px-6 py-3 text-right text-xs font-bold text-gray-500 uppercase tracking-wider">Action</th>
              </tr>
            </thead>
            <tbody className="bg-white divide-y divide-gray-100">
              {currentVersions.map((v) => (
                <VersionRow 
                  key={v.version}
                  version={v.version}
                  status={v.status}
                  lastUpdated={v.lastUpdated}
                  updatedBy={v.updatedBy}
                  isCurrent={v.isCurrent}
                  onView={() => handleViewVersion(v)}
                  onEdit={v.status === 'Draft' ? () => handleEditVersion(v) : undefined}
                />
              ))}
            </tbody>
          </table>
        </div>

        {versions.length > itemsPerPage && (
          <div className="px-6 py-4 bg-gray-50/50 border-t border-gray-200 flex items-center justify-between text-sm text-gray-600">
            <div>
              Showing <span className="font-semibold">{startIndex + 1}</span> to <span className="font-semibold">{Math.min(endIndex, versions.length)}</span> of <span className="font-semibold">{versions.length}</span>
            </div>
            <div className="flex items-center gap-2">
                <button onClick={() => handlePageChange(currentPage - 1)} disabled={currentPage === 1} className="p-1.5 rounded-md border border-gray-300 bg-white hover:bg-gray-50 disabled:opacity-50">
                  <ChevronLeft className="w-4 h-4" />
                </button>
                <span className="text-sm font-medium text-gray-700">Page {currentPage} of {totalPages}</span>
                <button onClick={() => handlePageChange(currentPage + 1)} disabled={currentPage === totalPages} className="p-1.5 rounded-md border border-gray-300 bg-white hover:bg-gray-50 disabled:opacity-50">
                  <ChevronRight className="w-4 h-4" />
                </button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

import React, { useState, useMemo } from 'react';
import { Plus } from 'lucide-react';
import { Navbar } from './components/Navbar';
import { Header } from './components/Header';
import { BlockList } from './components/BlockList';
import { FilterBar } from './components/FilterBar';
import { BlockModal } from './components/BlockModal';
import { HistoryModal } from './components/HistoryModal';
import { LogicModal } from './components/LogicModal';
import { TemplateList } from './components/TemplateList';
import { TestLogicModal } from './components/TestLogicModal';
import { NewTemplateModal } from './components/NewTemplateModal';
import { NewSkeletonModal } from './components/NewSkeletonModal';
import { PublishModal } from './components/PublishModal';
import { TemplateSettingsModal } from './components/TemplateSettingsModal';
import { SiteDetailsModal } from './components/SiteDetailsModal';
import { AuditLogModal } from './components/AuditLogModal';
import { AICloneModal, AICloneOption } from './components/AICloneModal';
import { MOCK_TEMPLATES, TEMPLATE_SKELETONS, getMockSitesForTemplate } from './constants';
import { Template, Block, BlockType, LogicRule, Site, Skeleton, BlockHistoryEntry } from './types';

export function App() {
  const [view, setView] = useState<'list' | 'builder'>('list');
  const [templates, setTemplates] = useState<Template[]>(MOCK_TEMPLATES || []);
  const [template, setTemplate] = useState<Template>(() => {
    return (templates && templates.length > 0) ? templates[0] : null as any;
  });
  const [viewingVersion, setViewingVersion] = useState<string | null>(null);
  const [skeletons, setSkeletons] = useState<Skeleton[]>(TEMPLATE_SKELETONS || []);

  const [expandedBlockIds, setExpandedBlockIds] = useState<Set<string>>(new Set());

  const [sitesByTemplate, setSitesByTemplate] = useState<Record<string, Site[]>>(() => {
    const initialSites: Record<string, Site[]> = {};
    if (MOCK_TEMPLATES) {
      MOCK_TEMPLATES.forEach(t => {
        initialSites[t.id] = getMockSitesForTemplate(t.id, t.version);
      });
    }
    return initialSites;
  });

  const [editingBlock, setEditingBlock] = useState<Block | null>(null);
  const [isModalOpen, setIsModalOpen] = useState(false);

  const [isHistoryOpen, setIsHistoryOpen] = useState(false);
  const [historyBlock, setHistoryBlock] = useState<Block | null>(null);

  const [isLogicModalOpen, setIsLogicModalOpen] = useState(false);
  const [logicBlockId, setLogicBlockId] = useState<string | null>(null);

  const [isTestLogicOpen, setIsTestLogicOpen] = useState(false);
  const [isNewTemplateModalOpen, setIsNewTemplateModalOpen] = useState(false);
  const [isNewSkeletonModalOpen, setIsNewSkeletonModalOpen] = useState(false);
  const [editingSkeleton, setEditingSkeleton] = useState<Skeleton | null>(null);
  const [isPublishModalOpen, setIsPublishModalOpen] = useState(false);
  const [isSettingsModalOpen, setIsSettingsModalOpen] = useState(false);
  const [isSiteDetailsModalOpen, setIsSiteDetailsModalOpen] = useState(false);
  const [isAuditLogOpen, setIsAuditLogOpen] = useState(false);
  const [isAICloneModalOpen, setIsAICloneModalOpen] = useState(false);
  const [blockToCloneId, setBlockToCloneId] = useState<string | null>(null);
  const [showSaveNotification, setShowSaveNotification] = useState(false);

  const [filterType, setFilterType] = useState<BlockType | 'All'>('All');
  const [searchQuery, setSearchQuery] = useState('');
  const [showMismatchOnly, setShowMismatchOnly] = useState(false);
  const [showDerived, setShowDerived] = useState(true);

  const headerTemplate = useMemo(() => {
    if (!template) return null;
    if (viewingVersion && viewingVersion !== template.version) {
       const historyItem = template.history?.find(h => h.version === viewingVersion);
       if (historyItem) {
          return {
             ...template,
             version: viewingVersion,
             lastUpdated: historyItem.lastUpdated,
             updatedBy: historyItem.updatedBy,
             blocks: historyItem.blocksSnapshot,
             status: 'Snapshot' as any
          };
       }
    }
    return template;
  }, [template, viewingVersion]);

  const filteredBlocks = useMemo(() => {
    if (!headerTemplate) return [];

    let blocks = [...headerTemplate.blocks];

    if (filterType !== 'All') {
      blocks = blocks.filter(b => b.type === filterType);
    }

    if (searchQuery) {
      blocks = blocks.filter(b => 
        b.contentName.toLowerCase().includes(searchQuery.toLowerCase()) || 
        (b.content && b.content.toLowerCase().includes(searchQuery.toLowerCase()))
      );
    }

    if (showMismatchOnly) {
       blocks = blocks.filter(b => {
          if (!b.isCloned || !b.clonedFrom) return false;
          const parent = headerTemplate.blocks.find(p => p.id === b.clonedFrom);
          return parent && parent.version !== b.derivedFromVersion;
       });
    }

    if (!showDerived) {
       blocks = blocks.filter(b => !b.isCloned);
    }

    return blocks;
  }, [headerTemplate, filterType, searchQuery, showMismatchOnly, showDerived]);

  const areAllExpanded = useMemo(() => {
    if (filteredBlocks.length === 0) return false;
    return filteredBlocks.every(b => expandedBlockIds.has(b.id));
  }, [filteredBlocks, expandedBlockIds]);

  const handleUpdateSites = (templateId: string, siteIds: string[]) => {
    setSitesByTemplate(prev => {
      const tmpl = templates.find(t => t.id === templateId);
      if (!tmpl) return prev;

      // Determine target version: If draft, use previous (stable). If stable, use current.
      let targetVersion = tmpl.version;
      if (tmpl.status === 'Draft' && tmpl.previousVersion) {
        targetVersion = tmpl.previousVersion;
      }

      const currentSites = prev[templateId] || [];
      const updatedSites = currentSites.map(s => {
        if (siteIds.includes(s.id)) {
          return {
            ...s,
            version: targetVersion,
            lastUpdated: new Date().toLocaleDateString('en-GB').replace(/\//g, '.')
          };
        }
        return s;
      });

      return {
        ...prev,
        [templateId]: updatedSites
      };
    });
  };

  const handleCreateTemplate = (name: string, skeletonId: string) => {
    const skeleton = skeletons.find(s => s.id === skeletonId);

    const newTemplate: Template = {
      id: `tmpl_${Date.now()}`,
      name: name,
      skeleton: skeleton ? skeleton.name : 'Custom',
      version: '0.1',
      previousVersion: '',
      lastUpdated: new Date().toLocaleDateString('en-GB').replace(/\//g, '.'),
      updatedBy: 'Current User',
      status: 'Draft',
      blocks: skeleton ? skeleton.blocks.map((b, i) => ({
         ...b,
         id: `blk_${Date.now()}_${i}`,
         version: '0.1',
         lastUpdated: new Date().toLocaleDateString('en-GB').replace(/\//g, '.'),
         history: [],
         isSyncing: false,
         hasEditHistory: false,
         rules: []
      })) : [],
      history: []
    };

    setTemplates([newTemplate, ...templates]);
    setTemplate(newTemplate);
    setSitesByTemplate(prev => ({ ...prev, [newTemplate.id]: [] }));
    setIsNewTemplateModalOpen(false);
    setView('builder');
  };

  const handleSelectTemplate = (tmpl: Template) => {
     setTemplate(tmpl);
     setViewingVersion(null);
     setView('builder');
  };

  const handleSelectVersion = (tmpl: Template, version: string) => {
     setTemplate(tmpl);
     setViewingVersion(version);
     setView('builder');
  };

  const handleCreateSkeleton = (name: string, description: string, blocks: any[]) => {
     const newSkeleton: Skeleton = {
        id: `sk_${Date.now()}`,
        name,
        description,
        status: 'Active',
        blocks: blocks.map(b => ({
           type: b.type,
           contentName: b.name,
           content: b.content,
           version: '1.0',
           lastUpdated: new Date().toLocaleDateString('en-GB').replace(/\//g, '.'),
           history: [],
           isSyncing: false,
           hasEditHistory: false,
           rules: []
        }))
     };
     setSkeletons([...skeletons, newSkeleton]);
     setIsNewSkeletonModalOpen(false);
  };

  const handleEditSkeleton = (updatedSkeleton: any) => {
      // Logic would be here to update skeleton definition
  };

  const handleSaveBlock = (id: string, name: string, type: BlockType, content: string, rules: LogicRule[], associatedDomainIds?: string[]) => {
    if (!template) return;

    // Check if updating existing or creating new
    const isNew = id.startsWith('temp_new');

    const newBlockVersion = isNew ? '0.1' : (
       // Increment minor version logic could be here, simplified for now
       '1.1' 
    );

    const updatedBlock: Block = {
       id: isNew ? `blk_${Date.now()}` : id,
       type,
       contentName: name,
       content,
       version: newBlockVersion,
       lastUpdated: new Date().toLocaleDateString('en-GB').replace(/\//g, '.'),
       hasEditHistory: true,
       isSyncing: false,
       history: isNew ? [] : [
          // Push old state to history
          ...(template.blocks.find(b => b.id === id)?.history || []),
          {
             version: template.blocks.find(b => b.id === id)?.version || '0.0',
             templateVersion: template.version,
             updatedAt: new Date().toISOString(),
             editedBy: 'Current User',
             changeDescription: 'Content update',
             contentSnapshot: template.blocks.find(b => b.id === id)?.content || ''
          }
       ],
       rules,
       associatedDomainIds
    };

    const newBlocks = isNew 
       ? [...template.blocks, updatedBlock]
       : template.blocks.map(b => b.id === id ? updatedBlock : b);

    // Update template state
    const newTemplate = {
       ...template,
       blocks: newBlocks,
       lastUpdated: new Date().toLocaleDateString('en-GB').replace(/\//g, '.')
    };

    setTemplates(templates.map(t => t.id === template.id ? newTemplate : t));
    setTemplate(newTemplate);

    // Show save success notification
    setShowSaveNotification(true);
    setTimeout(() => setShowSaveNotification(false), 3000);
  };

  const handleDeleteBlock = (id: string) => {
    if (!template) return;
    const newTemplate = {
       ...template,
       blocks: template.blocks.filter(b => b.id !== id),
       lastUpdated: new Date().toLocaleDateString('en-GB').replace(/\//g, '.')
    };
    setTemplates(templates.map(t => t.id === template.id ? newTemplate : t));
    setTemplate(newTemplate);
  };

  const handleDuplicateBlock = (id: string) => {
    setBlockToCloneId(id);
    setIsAICloneModalOpen(true);
  };

  const handleConfirmClone = (option: AICloneOption) => {
     if (!template || !blockToCloneId) return;
     const originalBlock = template.blocks.find(b => b.id === blockToCloneId);
     if (!originalBlock) return;

     let newContent = originalBlock.content || '';
     let newName = `${originalBlock.contentName} (Copy)`;

     if (option === 'simplify') {
         newContent = `[AI Simplified] ${newContent}`;
         newName = `${originalBlock.contentName} (Simplified)`;
     } else if (option === 'formal') {
         newContent = `[AI Formal] ${newContent}`;
         newName = `${originalBlock.contentName} (Formal)`;
     }
     // ... handle other AI options ...

     const newBlock: Block = {
        ...originalBlock,
        id: `blk_${Date.now()}`,
        contentName: newName,
        content: newContent,
        isCloned: true,
        clonedFrom: originalBlock.id,
        derivedFromVersion: originalBlock.version,
        version: '0.1',
        history: [],
        rules: originalBlock.rules ? [...originalBlock.rules] : [] // Copy logic too?
     };

     // Insert after original
     const index = template.blocks.findIndex(b => b.id === blockToCloneId);
     const newBlocks = [...template.blocks];
     newBlocks.splice(index + 1, 0, newBlock);

     const newTemplate = { ...template, blocks: newBlocks };
     setTemplates(templates.map(t => t.id === template.id ? newTemplate : t));
     setTemplate(newTemplate);

     setIsAICloneModalOpen(false);
     setBlockToCloneId(null);
  };

  const handleToggleExpandAll = () => {
    if (areAllExpanded) {
      setExpandedBlockIds(new Set());
    } else {
      setExpandedBlockIds(new Set(filteredBlocks.map(b => b.id)));
    }
  };

  const handleToggleExpand = (id: string) => {
     const newSet = new Set(expandedBlockIds);
     if (newSet.has(id)) newSet.delete(id);
     else newSet.add(id);
     setExpandedBlockIds(newSet);
  };

  const handleAddLogic = (blockId: string) => {
     setLogicBlockId(blockId);
     setIsLogicModalOpen(true);
  };

  const handleSaveLogic = (rule: Omit<LogicRule, 'id'>) => {
     if (!template || !logicBlockId) return;

     const newRule: LogicRule = {
        ...rule,
        id: `rule_${Date.now()}`
     };

     const newBlocks = template.blocks.map(b => {
        if (b.id === logicBlockId) {
           return { ...b, rules: [...(b.rules || []), newRule] };
        }
        return b;
     });

     const newTemplate = { ...template, blocks: newBlocks };
     setTemplates(templates.map(t => t.id === template.id ? newTemplate : t));
     setTemplate(newTemplate);
     setLogicBlockId(null);
  };

  const handleDeleteLogic = (blockId: string, ruleId: string) => {
     if (!template) return;
     const newBlocks = template.blocks.map(b => {
        if (b.id === blockId) {
           return { ...b, rules: b.rules.filter(r => r.id !== ruleId) };
        }
        return b;
     });
     const newTemplate = { ...template, blocks: newBlocks };
     setTemplates(templates.map(t => t.id === template.id ? newTemplate : t));
     setTemplate(newTemplate);
  };

  const handleUpdateNote = (blockId: string, note: string) => {
      if (!template) return;
      const newBlocks = template.blocks.map(b => b.id === blockId ? { ...b, notes: note } : b);
      const newTemplate = { ...template, blocks: newBlocks };
      setTemplates(templates.map(t => t.id === template.id ? newTemplate : t));
      setTemplate(newTemplate);
  };

  const handleConfirmPublish = (templateId: string) => {
      const tmpl = templates.find(t => t.id === templateId);
      if (!tmpl) return;

      // Logic to bump version from 1.1 Draft -> 2.0 Published
      // For simplicity, just set to Rolling Out
      const newTemplate: Template = {
         ...tmpl,
         status: 'Rolling Out',
         // If we were at 1.1, new published is 2.0? Or if 0.1 -> 1.0
         version: tmpl.version.endsWith('.0') ? tmpl.version : (Math.floor(parseFloat(tmpl.version)) + 1) + '.0',
         previousVersion: tmpl.version
      };

      setTemplates(templates.map(t => t.id === templateId ? newTemplate : t));
      setTemplate(newTemplate);
      setIsPublishModalOpen(false);
  };

  return (
    <div className="min-h-screen bg-gray-50 text-gray-900 font-sans">
      <Navbar />

      <main className="max-w-7xl mx-auto px-6 py-8">
        {view === 'list' ? (
           <TemplateList 
              templates={templates}
              skeletons={skeletons}
              sitesByTemplate={sitesByTemplate}
              onSelectTemplate={handleSelectTemplate}
              onSelectVersion={handleSelectVersion}
              onCreateTemplate={() => setIsNewTemplateModalOpen(true)}
              onCreateSkeleton={() => setIsNewSkeletonModalOpen(true)}
              onEditSkeleton={setEditingSkeleton}
              onArchiveSkeleton={(id) => {}}
              onTestLogic={(t) => { setTemplate(t); setIsTestLogicOpen(true); }}
              onArchive={(id) => {}}
              onUpdateSite={() => {}} // Legacy
              onOpenSiteDetails={(t) => {
                 if(t) setTemplate(t);
                 setIsSiteDetailsModalOpen(true);
              }}
              onCreateDraft={(t) => {
                 // Create draft logic
                 const draft: Template = {
                    ...t,
                    id: `tmpl_${Date.now()}`,
                    version: (parseFloat(t.version) + 0.1).toFixed(1),
                    previousVersion: t.version,
                    status: 'Draft',
                    blocks: t.blocks.map(b => ({ ...b })),
                    history: [...(t.history || []), { 
                       version: t.version, 
                       lastUpdated: t.lastUpdated, 
                       updatedBy: t.updatedBy || 'User',
                       blocksSnapshot: t.blocks
                    }]
                 };
                 setTemplates([draft, ...templates]);
                 setTemplate(draft);
                 setView('builder');
              }}
           />
        ) : (
           <>
              <Header 
                 template={headerTemplate!}
                 selectedVersion={headerTemplate!.version}
                 isReadOnly={headerTemplate!.status !== 'Draft'}
                 realStatus={headerTemplate!.status}
                 onBack={() => { setView('list'); setViewingVersion(null); }}
                 onTestLogic={() => setIsTestLogicOpen(true)}
                 onPublish={() => setIsPublishModalOpen(true)}
                 onOpenSettings={() => setIsSettingsModalOpen(true)}
                 onUnlock={() => {}}
                 onSaveDraft={() => {}}
                 onOpenAuditLog={() => setIsAuditLogOpen(true)}
              />

              <FilterBar 
                 selectedType={filterType}
                 onTypeChange={setFilterType}
                 searchQuery={searchQuery}
                 onSearchChange={setSearchQuery}
                 showMismatchOnly={showMismatchOnly}
                 onToggleMismatch={() => setShowMismatchOnly(!showMismatchOnly)}
                 showDerived={showDerived}
                 onToggleDerived={() => setShowDerived(!showDerived)}
                 areAllExpanded={areAllExpanded}
                 onToggleExpandAll={handleToggleExpandAll}
              />

              <BlockList 
                blocks={filteredBlocks}
                allBlocks={headerTemplate!.blocks}
                isReadOnly={headerTemplate!.status !== 'Draft'}
                onToggleExpand={handleToggleExpand}
                onDeleteBlock={handleDeleteBlock}
                onDuplicateBlock={handleDuplicateBlock}
                onEditContent={(b) => { setEditingBlock(b); setIsModalOpen(true); }}
                onShowHistory={(b) => { setHistoryBlock(b); setIsHistoryOpen(true); }}
                onAddLogic={handleAddLogic}
                onDeleteLogic={handleDeleteLogic}
                onRevertBlock={() => {}}
                onToggleDisable={(id) => {
                    if (!template) return;
                    const newBlocks = template.blocks.map(b => b.id === id ? { ...b, isDisabled: !b.isDisabled } : b);
                    const newTemplate = { ...template, blocks: newBlocks };
                    setTemplates(templates.map(t => t.id === template.id ? newTemplate : t));
                    setTemplate(newTemplate);
                }}
                onReorderBlocks={(dragId, targetId) => {
                    if (!template) return;
                    const dragIndex = template.blocks.findIndex(b => b.id === dragId);
                    const targetIndex = template.blocks.findIndex(b => b.id === targetId);
                    if (dragIndex === -1 || targetIndex === -1) return;

                    const newBlocks = [...template.blocks];
                    const [draggedItem] = newBlocks.splice(dragIndex, 1);
                    newBlocks.splice(targetIndex, 0, draggedItem);

                    const newTemplate = { ...template, blocks: newBlocks };
                    setTemplates(templates.map(t => t.id === template.id ? newTemplate : t));
                    setTemplate(newTemplate);
                }}
                onUpdateNote={handleUpdateNote}
                onAddBlock={(afterId) => {
                   setEditingBlock({
                      id: `temp_new_${Date.now()}`,
                      contentName: 'Add content',
                      type: 'Universal',
                      content: '',
                      version: '0.1',
                      lastUpdated: '',
                      hasEditHistory: false,
                      isSyncing: false,
                      history: [],
                      rules: []
                   });
                   setIsModalOpen(true);
                }}
                canReorder={headerTemplate!.status === 'Draft' && !searchQuery && filterType === 'All'}
              />
           </>
        )}
      </main>

      {/* Modals */}
      <BlockModal 
        isOpen={isModalOpen}
        onClose={() => setIsModalOpen(false)}
        onSave={handleSaveBlock}
        initialBlock={editingBlock}
        existingBlocks={template?.blocks || []}
        parentBlock={editingBlock?.isCloned ? template?.blocks.find(b => b.id === editingBlock.clonedFrom) : undefined}
      />

      <HistoryModal 
        isOpen={isHistoryOpen}
        onClose={() => setIsHistoryOpen(false)}
        block={historyBlock}
        currentTemplateVersion={template?.version}
      />

      <LogicModal 
        isOpen={isLogicModalOpen}
        onClose={() => setIsLogicModalOpen(false)}
        onSave={handleSaveLogic}
      />

      <TestLogicModal 
        isOpen={isTestLogicOpen}
        onClose={() => setIsTestLogicOpen(false)}
        template={template}
        sites={sitesByTemplate[template?.id] || []}
      />

      <NewTemplateModal
         isOpen={isNewTemplateModalOpen}
         onClose={() => setIsNewTemplateModalOpen(false)}
         onCreate={handleCreateTemplate}
         skeletons={skeletons}
      />

      <NewSkeletonModal 
         isOpen={isNewSkeletonModalOpen}
         onClose={() => setIsNewSkeletonModalOpen(false)}
         onSave={handleCreateSkeleton}
         initialSkeleton={editingSkeleton}
      />

      <PublishModal 
         isOpen={isPublishModalOpen}
         onClose={() => setIsPublishModalOpen(false)}
         templateId={template?.id}
         templateName={template?.name || ''}
         currentVersion={template?.version || ''}
         status={template?.status || 'Draft'}
         sites={sitesByTemplate[template?.id] || []}
         onConfirm={handleConfirmPublish}
         onConfirmUpdates={handleUpdateSites}
      />

      <TemplateSettingsModal
         isOpen={isSettingsModalOpen}
         onClose={() => setIsSettingsModalOpen(false)}
         template={template}
      />

      <SiteDetailsModal 
         isOpen={isSiteDetailsModalOpen}
         onClose={() => setIsSiteDetailsModalOpen(false)}
         template={template}
         allTemplates={templates}
         sites={sitesByTemplate[template?.id] || []}
         onUpdateSites={handleUpdateSites}
         onSelectTemplate={setTemplate}
      />

      <AuditLogModal 
         isOpen={isAuditLogOpen}
         onClose={() => setIsAuditLogOpen(false)}
         template={template!}
      />

      <AICloneModal 
         isOpen={isAICloneModalOpen}
         onClose={() => setIsAICloneModalOpen(false)}
         onConfirm={handleConfirmClone}
         blockName={template?.blocks.find(b => b.id === blockToCloneId)?.contentName || ''}
      />

      {/* Notifications */}
      {showSaveNotification && (
         <div className="fixed bottom-6 right-6 bg-gray-900 text-white px-4 py-3 rounded-lg shadow-lg flex items-center gap-3 animate-in slide-in-from-bottom-5 fade-in duration-300 z-50">
            <div className="bg-green-500 rounded-full p-1">
               <svg className="w-3 h-3 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="3">
                  <path strokeLinecap="round" strokeLinejoin="round" d="M5 13l4 4L19 7" />
               </svg>
            </div>
            <span className="text-sm font-medium">Changes saved successfully</span>
         </div>
      )}
    </div>
  );
}

import React, { useState, useEffect, useMemo } from 'react';
import { X, Building2, RefreshCw, CheckCircle2, ArrowRight, Square, CheckSquare, ChevronDown, Search, Filter } from 'lucide-react';
import { Site, Template } from '../types';

const getStatusStyles = (status: string) => {
  switch (status) {
    case 'Active': return 'text-emerald-700 bg-emerald-50 border-emerald-200';
    case 'Needs Update': return 'text-amber-700 bg-amber-50 border-amber-200';
    default: return 'text-gray-700 bg-gray-50 border-gray-200';
  }
};

interface SiteDetailsModalProps {
  isOpen: boolean;
  onClose: () => void;
  template: Template | null;
  allTemplates: Template[];
  sites: Site[];
  onUpdateSites: (templateId: string, siteIds: string[]) => void;
  onSelectTemplate: (template: Template) => void;
}

export const SiteDetailsModal: React.FC<SiteDetailsModalProps> = ({ isOpen, onClose, template, allTemplates, sites, onUpdateSites, onSelectTemplate }) => {
  const [selectedSiteIds, setSelectedSiteIds] = useState<Set<string>>(new Set());
  const [searchQuery, setSearchQuery] = useState('');
  const [statusFilter, setStatusFilter] = useState<'All' | 'Needs Update' | 'Active'>('All');
  const [versionFilter, setVersionFilter] = useState<string>('All');

  // Use the rolling/published version if we are currently looking at a draft
  const activeVersion = useMemo(() => {
    if (!template) return '';
    // If it's a draft, the "target" for updates is the previous version (the one currently live/rolling out)
    if (template.status === 'Draft' && template.previousVersion) return template.previousVersion;
    return template.version;
  }, [template]);

  // Only allow updates if the target version is a major release (X.0)
  const isTargetMajor = activeVersion.endsWith('.0');

  useEffect(() => {
    // Reset selection when template changes or modal opens
    setSelectedSiteIds(new Set());
    setSearchQuery('');
    setStatusFilter('All');
    setVersionFilter('All');
  }, [isOpen, template?.id]);

  const uniqueVersions = useMemo(() => {
    return Array.from(new Set(sites.map(s => s.version))).sort((a, b) => parseFloat(b as string) - parseFloat(a as string));
  }, [sites]);

  const filteredSites = useMemo(() => {
    return sites.filter(site => {
      // Search
      if (searchQuery && !site.name.toLowerCase().includes(searchQuery.toLowerCase())) {
        return false;
      }

      const needsUpdate = site.version !== activeVersion && isTargetMajor;

      // Status Filter
      if (statusFilter === 'Needs Update' && !needsUpdate) return false;
      if (statusFilter === 'Active' && needsUpdate) return false;

      // Version Filter
      if (versionFilter !== 'All' && site.version !== versionFilter) return false;

      return true;
    });
  }, [sites, searchQuery, statusFilter, versionFilter, activeVersion, isTargetMajor]);

  if (!isOpen || !template) return null;

  // Calculating bulk actions based on filtered view
  const sitesNeedingUpdateInView = filteredSites.filter(s => s.version !== activeVersion && isTargetMajor);
  const canUpdateCount = sitesNeedingUpdateInView.length;

  // Check if all *updateable* sites in current view are selected
  const areAllUpdateableSelected = canUpdateCount > 0 && sitesNeedingUpdateInView.every(s => selectedSiteIds.has(s.id));

  const handleToggleSelect = (siteId: string) => {
    const newSelected = new Set(selectedSiteIds);
    if (newSelected.has(siteId)) {
      newSelected.delete(siteId);
    } else {
      newSelected.add(siteId);
    }
    setSelectedSiteIds(newSelected);
  };

  const handleSelectAll = () => {
    if (areAllUpdateableSelected) {
      // Deselect all visible updateable sites
      const newSelected = new Set(selectedSiteIds);
      sitesNeedingUpdateInView.forEach(s => newSelected.delete(s.id));
      setSelectedSiteIds(newSelected);
    } else {
      // Select all visible updateable sites
      const newSelected = new Set(selectedSiteIds);
      sitesNeedingUpdateInView.forEach(s => newSelected.add(s.id));
      setSelectedSiteIds(newSelected);
    }
  };

  const handleUpdateSelected = () => {
    onUpdateSites(template.id, Array.from(selectedSiteIds));
    setSelectedSiteIds(new Set());
  };

  const handleUpdateSingle = (siteId: string) => {
     onUpdateSites(template.id, [siteId]);
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-gray-900/40 backdrop-blur-sm p-4 animate-in fade-in duration-200">
      <div className="bg-white rounded-2xl shadow-2xl w-full max-w-4xl overflow-hidden flex flex-col max-h-[90vh] ring-1 ring-gray-200">
        {/* Header */}
        <div className="flex items-center justify-between p-6 border-b border-gray-100 bg-white">
          <div className="flex items-center gap-3">
            <div className="p-2 bg-gray-100 text-gray-600 rounded-lg">
              <Building2 className="w-5 h-5" />
            </div>
            <div>
              <h2 className="text-xl font-semibold text-gray-900">Manage Sites</h2>
              <p className="text-sm text-gray-500 mt-1">Review and deploy version updates to participating sites.</p>
            </div>
          </div>
          <button onClick={onClose} className="p-2 text-gray-400 hover:text-gray-600 rounded-full hover:bg-gray-100 transition-colors">
            <X className="w-5 h-5" />
          </button>
        </div>

        {/* Template Info Sub-header */}
        <div className="px-6 py-4 bg-gray-50 border-b border-gray-200 flex flex-col sm:flex-row sm:items-center justify-between gap-4">
           <div className="flex items-center gap-2">
             <span className="text-sm font-medium text-gray-700">Target Release:</span>
             <span className="text-sm font-bold text-gray-900">{template.name}</span>
             <span className="px-2 py-0.5 rounded-full bg-indigo-50 text-indigo-700 border border-indigo-100 text-[10px] font-mono font-bold">v{activeVersion}</span>
           </div>
        </div>

        {/* Filters Toolbar */}
        <div className="px-6 py-3 border-b border-gray-200 bg-white grid grid-cols-12 gap-4 items-center">
            {/* Search */}
            <div className="col-span-12 sm:col-span-5 relative">
                <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
                <input 
                  type="text" 
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                  placeholder="Search sites..." 
                  className="w-full pl-9 pr-3 py-2 text-sm border border-gray-200 rounded-lg bg-gray-50 text-gray-900 focus:bg-white focus:outline-none focus:ring-2 focus:ring-indigo-100 focus:border-indigo-300 transition-all placeholder:text-gray-400"
                />
            </div>

            {/* Filters */}
            <div className="col-span-6 sm:col-span-3">
               <div className="relative">
                  <select 
                    value={statusFilter}
                    onChange={(e) => setStatusFilter(e.target.value as any)}
                    className="w-full pl-3 pr-8 py-2 text-sm border border-gray-200 rounded-lg appearance-none bg-white focus:outline-none focus:ring-2 focus:ring-indigo-100 focus:border-indigo-300 cursor-pointer text-gray-600"
                  >
                    <option value="All">All Status</option>
                    <option value="Needs Update">Needs Update</option>
                    <option value="Active">Active</option>
                  </select>
                  <Filter className="absolute right-3 top-1/2 -translate-y-1/2 w-3.5 h-3.5 text-gray-400 pointer-events-none" />
               </div>
            </div>

            <div className="col-span-6 sm:col-span-4">
               <div className="relative">
                  <select 
                    value={versionFilter}
                    onChange={(e) => setVersionFilter(e.target.value)}
                    className="w-full pl-3 pr-8 py-2 text-sm border border-gray-200 rounded-lg appearance-none bg-white focus:outline-none focus:ring-2 focus:ring-indigo-100 focus:border-indigo-300 cursor-pointer text-gray-600"
                  >
                    <option value="All">All Versions</option>
                    {uniqueVersions.map(v => (
                      <option key={v as string} value={v as string}>Version {v as string}</option>
                    ))}
                  </select>
                  <ChevronDown className="absolute right-3 top-1/2 -translate-y-1/2 w-3.5 h-3.5 text-gray-400 pointer-events-none" />
               </div>
            </div>
        </div>

        {/* Body */}
        <div className="flex-1 overflow-y-auto bg-white">
          <div className="p-6">
            <div className="bg-white rounded-xl border border-gray-200 shadow-sm overflow-hidden">
              {/* Table Header */}
              <div className="grid grid-cols-12 gap-4 px-6 py-3 bg-gray-50 text-xs font-semibold text-gray-500 uppercase tracking-wider border-b border-gray-200 items-center">
                <div className="col-span-5 flex items-center gap-3">
                   <button 
                      onClick={handleSelectAll} 
                      disabled={canUpdateCount === 0}
                      className="text-gray-400 hover:text-indigo-600 transition-colors disabled:opacity-30 disabled:cursor-not-allowed"
                      title={areAllUpdateableSelected ? "Deselect All Needs Update" : "Select All Needs Update"}
                    >
                        {areAllUpdateableSelected && canUpdateCount > 0 ? (
                          <CheckSquare className="w-4 h-4 text-indigo-600" />
                        ) : (
                          <Square className="w-4 h-4" />
                        )}
                    </button>
                   <span>Site Name</span>
                </div>
                <div className="col-span-3">Current Version</div>
                <div className="col-span-2">Status</div>
                <div className="col-span-2 text-right">Action</div>
              </div>

              {/* Site List */}
              {filteredSites.length > 0 ? (
                <div className="divide-y divide-gray-100">
                  {filteredSites.map(site => {
                    // Logic: Needs Update if versions differ AND target is major version
                    const needsUpdate = site.version !== activeVersion && isTargetMajor;
                    const statusLabel = needsUpdate ? 'Needs Update' : 'Active';
                    const isSelected = selectedSiteIds.has(site.id);

                    return (
                      <div key={site.id} className={`grid grid-cols-12 gap-4 px-6 py-4 items-center text-sm transition-colors ${isSelected ? 'bg-indigo-50/30' : ''}`}>
                        <div className="col-span-5 flex items-center gap-3">
                          {needsUpdate ? (
                             <button onClick={() => handleToggleSelect(site.id)} className="text-gray-300 hover:text-indigo-600">
                               {isSelected ? <CheckSquare className="w-4 h-4 text-indigo-600" /> : <Square className="w-4 h-4" />}
                             </button>
                          ) : (
                             <div className="w-4 h-4 flex items-center justify-center" title="Active">
                               <CheckCircle2 className="w-3.5 h-3.5 text-emerald-300" />
                             </div>
                          )}
                          <div className="flex flex-col">
                             <span className="font-medium text-gray-800 truncate" title={site.name}>{site.name}</span>
                             <span className="text-[10px] text-gray-400 font-mono">ID: {site.id}</span>
                          </div>
                        </div>
                        <div className="col-span-3 font-mono text-gray-600 flex items-center">
                          <span className={`px-2 py-0.5 rounded border ${needsUpdate ? 'bg-amber-50 border-amber-100 text-amber-700' : 'bg-gray-50 border-gray-200'}`}>v{site.version}</span>
                          {needsUpdate && (
                            <>
                              <ArrowRight className="w-3 h-3 mx-2 text-gray-300" />
                              <span className="font-bold text-indigo-700">v{activeVersion}</span>
                            </>
                          )}
                        </div>
                        <div className="col-span-2">
                          <span className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium border whitespace-nowrap ${getStatusStyles(statusLabel)}`}>
                            {statusLabel}
                          </span>
                        </div>
                        <div className="col-span-2 text-right">
                          {needsUpdate ? (
                            <button
                              onClick={() => handleUpdateSingle(site.id)}
                              className="text-xs font-semibold text-indigo-600 bg-indigo-50 hover:bg-indigo-100 px-3 py-1.5 rounded-md transition-colors flex items-center gap-1.5 ml-auto border border-indigo-100"
                            >
                              <RefreshCw className="w-3 h-3" /> Update
                            </button>
                          ) : (
                            <span className="text-xs font-medium text-emerald-600 flex items-center justify-end gap-1.5">
                              <CheckCircle2 className="w-4 h-4" /> Up-to-date
                            </span>
                          )}
                        </div>
                      </div>
                    );
                  })}
                </div>
              ) : (
                <div className="text-center py-12 text-sm text-gray-400 flex flex-col items-center">
                  <Search className="w-8 h-8 text-gray-200 mb-2" />
