                 return { ...b, content: `# Participant Information Sheet and Consent Form\n\n**(Prior to Enrolment)**\n\n**COVID-19: Pandemic infection is proven**`, version: '1.0', lastUpdated: '20.12.2024' };
             }
             return { ...b, version: '1.0', lastUpdated: '20.12.2024' };
          })
       }
    ]
  }
];

