                     </div>
                     <div className="col-span-2">
                        <label className="block text-xs font-medium text-gray-500 mb-1.5 uppercase">Operator</label>
                        <select 
                          value={newRuleOp}
                          onChange={(e) => setNewRuleOp(e.target.value as LogicOperator)}
